constraints:
-10^{9 }≤ x-coordinate, y-coordinate ≤ 10^{9}

expected time complexity: O(Log_{2}10^{9})
expected auxiliary space: O(1)

standard_solution_code:
def gcd(a, b):
	if b == 0:
		return a
	return gcd(b, a % b)

def get1(a1, a2):
	if a1[0] == a2[0]:
		return abs(a1[1] - a2[1]) - 1
	if a1[1] == a2[1]:
		return abs(a1[0] - a2[0]) - 1
	return gcd(abs(a1[0] - a2[0]), abs(a1[1] - a2[1])) - 1

class Solution:

	def InternalCount(self, p, q, r):
		boundary = get1(p, q) + get1(q, r) + get1(p, r)
		ar = abs(p[0] * (q[1] - r[1]) + q[0] * (r[1] - p[1]) + r[0] * (p[1] - q[1]))
		return (ar - boundary + 2) // 2 - 1
